<old_string>            # Parse successful response
            response.raise_for_status()
            return response.json()

        except requests.exceptions.RequestException as e:
            raise RuntimeError(f"Request failed: {str(e)}") from e
        except json.JSONDecodeError as e:
            raise RuntimeError(f"Invalid JSON response: {str(e)}") from e</old_string>
<new_string>            # Parse successful response
            response.raise_for_status()
            try:
                return response.json()
            except ValueError as e:
                # Handle cases where response.json() raises ValueError (e.g., invalid JSON)
                raise RuntimeError(f"Invalid response format: {str(e)}") from e

        except requests.exceptions.RequestException as e:
            raise RuntimeError(f"Request failed: {str(e)}") from e
        except json.JSONDecodeError as e:
            raise RuntimeError(f"Invalid JSON response: {str(e)}") from e</new_string>
